    public Object unmarshalData(String data) throws java.io.IOException, ClassNotFoundException {
        // Convert hex string to byte array
        // Using DatatypeConverter as it's imported and standard for this
        byte[] bytes = DatatypeConverter.parseHexBinary(data);
        // Alternatively, using the provided helper method:
        // byte[] bytes = hexStringToByteArray(data);

        // Create a ByteArrayInputStream from the bytes
        ByteArrayInputStream bis = new ByteArrayInputStream(bytes);

        // Create an ObjectInputStream to deserialize the object
        ObjectInputStream ois = new ObjectInputStream(bis);

        // Read the object
        Object obj = ois.readObject();

        // Close the streams
        ois.close();
        bis.close();

        return obj;
    }
}
