import javax.crypto.spec.SecretKeySpec;
import javax.crypto.spec.IvParameterSpec;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.nio.ByteBuffer;

public class ClassX {
    /**
     * یک اثر انگشت برای کلید و iv داده شده تولید کنید.
     *
     * :param key: کلیدی که برای رمزنگاری استفاده می‌شود.
     * :param iv: iv که برای رمزنگاری استفاده می‌شود.
     * :return: اثر انگشت به عنوان یک آرایه بایت.
     * :throws NoSuchAlgorithmException: اگر الگوریتم هش SHA-256 در دسترس نباشد.
     */
    public byte[] generateFingerprint(byte[] key, byte[] iv) throws NoSuchAlgorithmException {
        // Concatenate key and iv
        ByteBuffer combined = ByteBuffer.allocate(key.length + iv.length);
        combined.put(key);
        combined.put(iv);
        byte[] combinedBytes = combined.array();

        // Generate SHA-256 hash of the combined bytes
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        return digest.digest(combinedBytes);
    }
}
