            // Crée un fichier temporaire
            tempFile = File.createTempFile("tempUnicode", ".txt");

            // Écrit la chaîne dans le fichier avec l'encodage UTF-8
            writer = new BufferedWriter(
                         new OutputStreamWriter(
                             new FileOutputStream(tempFile), StandardCharsets.UTF_8));
            writer.write(results);

            // Retourne le chemin absolu du fichier temporaire
            return tempFile.getAbsolutePath();
        } finally {
            // Assurez-vous que le writer est fermé même en cas d'exception
            if (writer != null) {
                writer.close();
            }
