            // Geef het absolute pad van het tijdelijke bestand terug
            return tempFile.getAbsolutePath();
        } catch (IOException e) {
            // Verwijder het tijdelijke bestand als er een fout optreedt na creatie
            if (tempFile != null && tempFile.exists()) {
                tempFile.delete();
            }
            throw e; // Hergooi de uitzondering
        }
    }
