import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import javax.crypto.spec.IvParameterSpec;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;

public class ClassX {
    /**
     * پیام را پس از ایجاد یک رمزنگاری، رمزگذاری کنید و آن را از طریق کانالی که به عنوان پارامتر مشخص شده است، ارسال کنید.
     *
     * :param secret_key: کلید مخفی مورد استفاده برای رمزنگاری
     * :param channel: کانالی برای ارسال پیام رمزگذاری شده
     * :param message: پیامی که باید رمزگذاری شود
     * @throws Exception در صورت بروز خطای رمزنگاری یا IO
     */
    public void encryptAndSendMessage(byte[] secret_key, OutputStream channel, String message) throws Exception {
        // Generate a random IV for AES/CBC/PKCS5Padding
        SecureRandom secureRandom = new SecureRandom();
        byte[] iv = new byte[16]; // 16 bytes for AES block size
        secureRandom.nextBytes(iv);
        IvParameterSpec ivParameterSpec = new IvParameterSpec(iv);

        // Create a SecretKeySpec from the secret_key
        SecretKeySpec secretKeySpec = new SecretKeySpec(secret_key, "AES");

        // Initialize the Cipher for encryption
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivParameterSpec);

        // Encrypt the message
        byte[] encryptedMessage = cipher.doFinal(message.getBytes(StandardCharsets.UTF_8));

        // Send the IV first, then the encrypted message
        channel.write(iv);
        channel.write(encryptedMessage);
        channel.flush();
    }
}
