     * @return true, wenn das Bild erfolgreich gelöscht wurde oder nicht existierte; false, wenn ein Fehler beim Löschen auftrat.
     */
    public static boolean deleteImage(String path) {
        if (path == null || path.trim().isEmpty()) {
            // Path is invalid, consider it as not deleted successfully or nothing to delete
            return false; 
        }

        File imageFile = new File(path);

        if (imageFile.exists()) {
            if (imageFile.delete()) {
                // File existed and was successfully deleted
                return true;
            } else {
                // File existed but could not be deleted (e.g., locked by another process, permissions issue)
                System.err.println("Fehler: Bild konnte nicht gelöscht werden: " + path);
                return false;
            }
        } else {
            // File does not exist, so nothing to delete. Consider it a success in terms of "no longer there".
            return true;
        }
    }
}
