    /**
     * Haal de GitHub-gebruikersnaam uit het verzoek en retourneer de GitHub-informatie van de gebruiker met behulp van deze URL: https://api.github.com/users/{username}.
     *
     * @param username De GitHub-gebruikersnaam.
     * @return Een URI naar de GitHub API-informatie van de gebruiker, of null als de gebruikersnaam leeg of ongeldig is.
     */
    public URI getGitHubUserInfoUrl(String username) {
        if (username == null || username.trim().isEmpty()) {
            return null; // Of gooi een IllegalArgumentException
        }
        try {
            String urlString = String.format("https://api.github.com/users/%s", username.trim());
            return new URI(urlString);
        } catch (URISyntaxException e) {
            // Dit zou in principe niet moeten gebeuren met een correct geformatteerde URL en een geldige gebruikersnaam,
            // maar het is goed om de uitzondering af te handelen.
            e.printStackTrace(); // Log de fout
            return null;
        }
    }
}
