    public String getCleanContent(String content) {
        if (content == null || content.isEmpty()) {
            return content;
        }

        // Regex to match <script ...> ... </script> tags, case-insensitive and including attributes
        // Pattern.DOTALL ensures that '.' matches newlines as well, so it covers multi-line scripts.
        // Pattern.CASE_INSENSITIVE ensures that <script>, <SCRIPT>, etc., are matched.
