public class ClassX {

    private static final String STATIC_DIRECTORY_PATH = "/path/to/your/static/files"; // Replace with your actual static directory path

    /**
     * اقرأ اسم الملف من الطلب وأرسله كمرفق من الدليل الثابت.
     * Reads the filename from the request and sends it as an attachment from the static directory.
     *
     * @param filename The name of the file requested.
     * @return A File object representing the requested file in the static directory, or null if the filename is invalid.
     */
    public File getAttachmentFile(String filename) {
        if (filename == null || filename.trim().isEmpty()) {
            return null; // Or throw an IllegalArgumentException
        }
        // It's good practice to sanitize the filename to prevent directory traversal attacks
        // For simplicity, this example directly uses the filename, but in a real application,
        // you should validate and sanitize it carefully.
