    public org.w3c.dom.Element parseXmlFile(String file_path) {
        try {
            File xmlFile = new File(file_path);
            DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
            DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();
            Document doc = dBuilder.parse(xmlFile);
            doc.getDocumentElement().normalize(); // Optional: normalize the document
            return doc.getDocumentElement();
        } catch (javax.xml.parsers.ParserConfigurationException e) {
            System.err.println("Error configuring XML parser: " + e.getMessage());
            e.printStackTrace();
            return null;
        } catch (org.xml.sax.SAXException e) {
            System.err.println("Error parsing XML file: " + e.getMessage());
            e.printStackTrace();
            return null;
        } catch (java.io.IOException e) {
            System.err.println("Error reading XML file: " + e.getMessage());
            e.printStackTrace();
            return null;
        }
    }
}
