import org.w3c.dom.Document;
import org.xml.sax.SAXException;
import java.io.File;
import java.io.IOException;

public class ClassX {
    /**
     * 创建一个XML解析器，解析文件并返回根元素。
     * @param file_path: 要解析的XML文件的路径。
     * @return: XML文件的根元素。
     * @throws ParserConfigurationException 如果无法创建DocumentBuilder。
     * @throws SAXException 如果在解析XML时发生任何SAX错误。
     * @throws IOException 如果发生任何I/O错误。
     */
    public Document createXmlParser(String file_path)
            throws ParserConfigurationException, SAXException, IOException {
        // 获取DocumentBuilderFactory实例
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        // 从工厂获取DocumentBuilder实例
        DocumentBuilder builder = factory.newDocumentBuilder();
        // 解析XML文件并返回Document对象
        Document document = builder.parse(new File(file_path));
        // 返回根元素（Document对象本身就是整个XML文档的根）
        return document;
    }
}
