import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import org.w3c.dom.Element; // Import Element
import java.io.File;

public class ClassX {
    /**
     * Buatlah parser XML dan analisis file tersebut serta kembalikan elemen akar.
     * @param file_path: Jalur ke file XML yang akan dianalisis.
     * @return: Elemen akar dari file XML.
     */
    public Element parseXmlAndGetRoot(String file_path) {
        try {
            // Buat DocumentBuilderFactory
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            // Buat DocumentBuilder
            DocumentBuilder builder = factory.newDocumentBuilder();
            // Parse file XML
            Document document = builder.parse(new File(file_path));
            // Normalisasi dokumen (opsional, tapi sering direkomendasikan)
            document.getDocumentElement().normalize();
            // Kembalikan elemen akar
            return document.getDocumentElement();
        } catch (Exception e) {
            e.printStackTrace(); // Cetak stack trace untuk debugging
            return null; // Kembalikan null jika terjadi kesalahan
        }
    }
}
