     * :throws IOException: Jika terjadi kesalahan saat membaca file templat.
     */
    public String renderTemplate(Map<String, String> requestParams) throws IOException {
        String templatePath = "../assets/templates/template.html";
        String templateContent = new String(Files.readAllBytes(Paths.get(templatePath)));

        for (Map.Entry<String, String> entry : requestParams.entrySet()) {
            String placeholder = "{{" + entry.getKey() + "}}"; // Contoh placeholder: {{nama_parameter}}
            templateContent = templateContent.replace(placeholder, entry.getValue());
        }

        return templateContent;
    }
}
