import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    /**
     * בדוק אם ה-URL שניתן הוא URL תקין עם הפורמט הבא: (www|beta).example.com/
     * 
     * :param url: מיתר לחיפוש בו
     * :return: True אם יש התאמה, False אחרת
     */
    public boolean isUrlValid(String url) {
        // The pattern to match: (www|beta).example.com/
        // ^ asserts position at the start of the string.
        // (www|beta) matches "www" or "beta".
        // \\. matches a literal dot.
        // example\\.com matches "example.com" literally.
        // / matches a literal forward slash.
        // $ asserts position at the end of the string.
        String regex = "^(www|beta)\\.example\\.com/$";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(url);
        return matcher.matches();
    }
}
