import java.util.Objects;

public class ClassX {
    /**
     * Obtenha o nome da solicitação e envie-o de volta ao usuário neste formato: 'Olá <nome>!'.
     * @param name O nome a ser usado na saudação.
     * @return Uma string de saudação no formato 'Olá <nome>!'.
     */
    public String getNameAndReturn(String name) {
        // Garante que o nome não seja nulo para evitar NullPointerExceptions
        // e fornece uma string vazia ou um valor padrão se for nulo.
        String safeName = Objects.requireNonNullElse(name, ""); 
        return "Olá " + safeName + "!";
    }
}
