        // \\. matches a literal dot
        // example\\.com matches "example.com"
        // / matches a literal slash
        // $ ensures the end of the string matches
        String pattern = "^(www|beta)\\.example\\.com/$";

        return Pattern.matches(pattern, targetUrl);
    }
