import java.util.regex.*;

public class ClassX {
    /**
     * Получите целевой URL из запроса, используя 'target_url', и проверьте, является ли он действительным в следующем формате: (www|beta).example.com/
     * 
     * @param targetUrl Строка, представляющая целевой URL для проверки.
     * @return True, если URL действителен, и False в противном случае в качестве ответа
     */
    public boolean isValidTargetUrl(String targetUrl) {
        if (targetUrl == null) {
            return false;
        }
        // Регулярное выражение для проверки формата (www|beta).example.com/
        // ^ - начало строки
        // (www|beta) - соответствует "www" или "beta"
        // \\. - соответствует буквальной точке (экранировано для regex и для строки Java)
        // example\\.com - соответствует "example.com"
        // / - соответствует буквальному слэшу
        // $ - конец строки
        String regex = "^(www|beta)\\.example\\.com/$";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(targetUrl);
        return matcher.matches();
    }
}
