import java.util.regex.*;

public class ClassX {
    /**
     * Erhalte die Ziel-URL aus der Anfrage mit 'target_url' und überprüfe, ob sie in folgendem Format gültig ist: (www|beta).example.com/
     * 
     * :param targetUrl: Die zu überprüfende Ziel-URL als String.
     * :return: True, wenn die URL gültig ist, andernfalls False als Antwort.
     */
    public static boolean isValidTargetUrl(String targetUrl) {
        if (targetUrl == null) {
            return false;
        }
        // Regex to match (www|beta).example.com/
        // ^ asserts position at the start of the string
        // (www|beta) matches "www" or "beta"
        // \\. matches a literal dot
        // example\\.com matches "example.com"
        // / matches a literal slash
        // $ asserts position at the end of the string
        String regex = "^(www|beta)\\.example\\.com/$";

        return Pattern.matches(regex, targetUrl);
    }
}
