     */
    public Object evaluatePythonExpression(String inputStr) throws ScriptException {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine pythonEngine = manager.getEngineByName("python");

        if (pythonEngine == null) {
            // Handle the case where the Python engine is not available.
            // This typically means Nashorn (for JavaScript) is available by default,
            // but for Python, you might need Jython installed and configured.
            throw new IllegalStateException("Python ScriptEngine not found. Ensure Jython is in the classpath if running on a standard JVM.");
        }

        return pythonEngine.eval(inputStr);
    }
}
