import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;
import java.util.Map;

public class ClassX {
    /**
     * Ambil data dari permintaan menggunakan 'contents'.
     * Kembalikan isi file dengan mengevaluasinya menjadi sebuah kamus.
     *
     * @param contents String yang berisi data yang akan dievaluasi (misalnya, JSON atau objek JavaScript literal).
     * @return Sebuah Map yang merepresentasikan kamus yang dievaluasi, atau null jika terjadi kesalahan.
     * @throws ScriptException Jika terjadi kesalahan saat mengevaluasi konten.
     */
    public Map<String, Object> evaluateContentsAsDictionary(String contents) throws ScriptException {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // Atau "nashorn" untuk Java 8, "Graal.js" untuk Java 11+

        // Mengevaluasi string sebagai objek JavaScript
        Object result = engine.eval("(" + contents + ")"); // Bungkus dengan tanda kurung untuk memastikan evaluasi sebagai ekspresi objek

        // Jika hasil evaluasi adalah objek JavaScript, coba konversi ke Map Java
        if (result instanceof Map) {
            @SuppressWarnings("unchecked")
            Map<String, Object> dictionary = (Map<String, Object>) result;
            return dictionary;
