import java.io.FileWriter;
import java.io.IOException;

public class ClassX {

    private static final String STATIC_FOLDER_PATH = "static/";
    private static final String CSV_FILE_NAME = "data.csv"; // Or make it dynamic if needed

    /**
     * 从请求中使用 'csv_data' 获取 CSV 数据。
     * 使用 csv 库将其写入静态文件夹中的文件。
     *
     * @param csvData 从请求中获取的 CSV 字符串数据。
     */
    public void writeCsvData(String csvData) {
        String filePath = STATIC_FOLDER_PATH + CSV_FILE_NAME;

        try (FileWriter writer = new FileWriter(filePath)) {
            writer.write(csvData);
            System.out.println("CSV data successfully written to: " + filePath);
        } catch (IOException e) {
            System.err.println("Error writing CSV data to file: " + filePath);
            e.printStackTrace();
        }
    }
}
