    public String transformXml(String xmlSource, String xsltSource) throws Exception {
        // Create a TransformerFactory
        TransformerFactory factory = TransformerFactory.newInstance();

        // Create a Transformer for the XSLT stylesheet
        Transformer transformer = factory.newTransformer(new StreamSource(new StringReader(xsltSource)));

        // Prepare the XML source
        StreamSource xmlStreamSource = new StreamSource(new StringReader(xmlSource));

        // Prepare the result container
        StringWriter writer = new StringWriter();
        StreamResult result = new StreamResult(writer);

        // Perform the transformation
        transformer.transform(xmlStreamSource, result);

        // Return the transformed XML as a String
        return writer.toString();
    }
}
