import java.util.logging.Logger;

public class ClassX {

    private static final Logger logger = Logger.getLogger(ClassX.class.getName());

    /**
     * Represents a simplified request object for demonstration purposes.
     * In a real application, this would be an HttpServletRequest or similar.
     */
    public static class Request {
        private final java.util.Map<String, String> parameters;

        public Request(java.util.Map<String, String> parameters) {
            this.parameters = parameters;
        }

        public String getParameter(String name) {
            return parameters.get(name);
        }
    }

    /**
     * Get the name from the request using 'name' key and log it.
     * @param request The request object containing parameters.
     * @return The name, or null if not found.
     */
    public String getNameFromRequest(Request request) {
        if (request == null) {
            logger.warning("Received a null request object.");
            return null;
        }

        String name = request.getParameter("name");

        if (name != null && !name.trim().isEmpty()) {
            logger.info("Name retrieved from request: " + name);
        } else {
            logger.warning("Name parameter not found or was empty in the request.");
        }

        return name;
    }
}
